      "title": "# 제10조(노인당원의 지위와 권리)",
      "content": "①우리 당은 고령화 사회에 대비하여 노인의 정치참여 기회를 확대하고, 노인당원의 지위와 권리를 보장한다. <개정 2024.8.12.>\n\n②우리 당은 제1항의 실현을 위하여 당직과 공직선거의 후보자 추천에 있어서 당헌·당규로 정하는 바에 따라 노인당원이 일정 비율 이상 포함되도록 노력하여야 한다.\n\n③기타 필요한 사항은 당규로 정한다."
