      "content": "①우리 당은 노동의 가치를 존중하고 모든 노동자의 인간다운 삶을 보장하기 위한 정책을 실현하며, 특히 2012년 노동 대표성 보장원칙을 계승·발전시켜 노동부문 당원의 지위와 권리를 보장 한다. <개정 2024.8.12., 2026.2.3.>\n\n②우리 당은 제1항의 실현을 위하여 전국당원대회와 중앙위원회 등 대의기관에 노동 부문 당원을 일정 비율 이상 포함하며, 중앙당 및 시·도당의 주요당직과 각급 위원회의 구성에 있어 당헌·당규로 정하는 바에 따라 노동부문 당원이 100분의 10 이상 포함되도록 노력하여야 한다. <개정 2024.6.17., 2026.2.3.>\n\n③기타 필요한 사항은 당규로 정한다."
