      "category": "당헌",
      "section": "Ⅲ. 당 헌",
      "title": "# 제18조(전국당원대회준비위원회)",
      "content": "①당무위원회는 전국당원대회를 효율적으로 개최하기 위하여 전국당원대회준비위원회를 후보자 등록 신청 개시일 전 50일까지 설치한다. 단, 임시전국당원대회 개최 시에는 전국당원대회준비위원회를 후보자 등록 신청 개시일 전 30일까지 설치한다. <개정 2024.6.17., 2024.8.12., 2025.6.13.>\n\n②전국당원대회준비위원회는 대회의 준비와 진행에 관한 사무를 관장한다. 다만, 선거관리에 대하여는 중앙당선거관리위원회의 지시를 받아야 한다. <개정 2024.6.17.>\n\n③기타 필요한 사항은 당규로 정한다."
