      "content": "①의원총회는 국회 회기 중에는 주 1회 이상 개최를 원칙으로 하고, 최고위원회 또는 원내대표가 필요하다고 인정하거나 재적의원 3분의 1 이상의 요구가 있을 때 원내대표가 소집한다.\n\n②원내대표가 제1항의 규정에 위반하여 의원총회를 소집하지 아니한 때에는 원내수석부대표가 소집하되, 원내수석부대표가 소집하지 아니할 때에는 당대표가 소집권자를 지명한다.\n\n③상임고문은 의원총회에 참석하여 발언할 수 있다.\n\n④의원총회는 재적의원 3분의 1 이상의 출석으로 개의하고, 재적의원 과반수의 출석과 출석의원 과반수의 찬성으로 의결한다. 다만, 제51조제7호의 규정에 따른 국회의원의 제명은 재적의원 2분의 1 이상의 찬성으로 의결한다."
