      "content": "①공직선거 후보자로 확정된 자의 입후보등록이 불가능하거나, 당규로 정한 사유가 발생하는 때에는 당규로 정한 절차에 따라 추천을 무효로 하고 재추천할 수 있다.\n\n②후보등록기간 촉박 등의 상당한 사유가 있는 때에는 당무위원회에서 추천을 무효화 하고 후보자를 선정하여 재추천할 수 있다.\n\n③기타 필요한 사항은 당규로 정한다."
