      "content": "①당헌 개정 발의가 있을 경우 전국당원대회 의장 또는 중앙위원회 의장은 지체 없이 그 개정안을 공고하고 전국당원대회 또는 중앙위원회를 소집하여야 한다.\n\n②당헌 개정은 전국당원대회 재적 대의원 과반수의 찬성 또는 중앙위원회 재적 중앙위원 과반수의 찬성으로 의결한다.[전문개정 2024.6.17.]"
