      "title": "# 제115조(표결)",
      "content": "①대의기관의 결의와 소속 국회의원의 제명은 서면결의를 할 수 없다.\n\n②제1항의 의안을 제외한 모든 의안은 당헌·당규에 달리 정한 경우를 제외하고는 서면으로 결의할 수 없다. 다만, 당면과제에 대처하기 위하여 구성된 특별위원회나 특별기구및 소위원회 등의 경우 긴급한 사정이 있는 때에는 예외로 한다.\n\n③인사에 관한 표결은 당헌·당규에 다른 규정이 없으면 비밀투표로 한다. 다만, 이의를 제기하는 참석자가 없는 때에는 표결방법을 변경할 수 있다."
