      "category": "당규",
      "section": "Ⅳ. 당 규",
      "title": "# 제13조(서명)",
      "content": "회의록은 다음 각 호의 자가 확인하고 서명한다.\n\n1. 전국당원대회 : 전국당원대회 의장, 사무총장 <개정 2024.6.12.>\n\n2. 중앙위원회 : 중앙위원회 의장, 사무총장\n\n3. 당무위원회 : 당무위원회 의장, 사무총장 <개정 2021.4.23.>\n\n4. 최고위원회 : 사무총장\n\n5. 의원총회 : 원내수석부대표\n\n6. 지방의회 의원총회 : 시·도당위원장 <개정 2020.8.19.>"
