      "content": "①지역당원은 해당 시·도당에 소속되어 활동하고, 해당 시·도당이 관리하는 당원을 말한다.\n\n②정책당원은 노동·온라인·직능·재외국민 등의 부문에 소속되어 활동하고, 중앙당이 관리하는 당원을 말한다. 여기서 재외국민당원은 대한민국 국적을 가진 자로 외국에 거주하고 있는 당원을 말한다. <개정 2020.8.19.>\n\n③권리당원은 제1항 또는 제2항의 당원 중 당규로 정한 당비를 납부한 당원을 말한다.\n\n④청소년당원은 만 16세 이상 만 18세 미만인 당원을, 청년당원은 만 45세 이하인 당원을, 노인당원은 만 65세 이상인 당원을 말한다. <개정 2022.2.9.>\n\n⑤대학생당원은 만 29세 이하의 당원 중 대학생 또는 대학원생인 당원을 말한다.\n\n⑥백년당원은 일정기간 계속해서 당적을 보유하고 있고 당비 체납이 없는 당원을 말한다.\n\n⑦제6항의 백년당원은 월 1회를 기준으로 당비 체납이 없는 당원으로 하되, 구체적인 자격기준과 심사, 증빙방법 등은 당원자격심사위원회의 의결로 정한다."
