      "content": "①제명 또는 탈당한 지역당원은 제명 또는 탈당 당시의 소속 시·도당이 아닌 다른 시·도당 또는 중앙당에 입당 또는 복당할 수 없다.\n\n②제명 또는 탈당한 정책당원은 지역당원으로 시·도당에 입당 또는 복당할 수 없다."
