      "content": "①입당 또는 복당이 확정된 자는 정당법 제23조제2항에 따라 당원명부에 등재하고 당원증을 교부한다.\n\n②제1항의 당원증 교부는 당적증명서 발급으로 대체할 수 있다.\n\n③당원증에는 성명, 주소, 생년월일, 교부일자 등을 기재하고 당인을 날인하여야 한다."
