      "category": "당규",
      "section": "Ⅳ. 당 규",
      "title": "# 제34조(토론권)",
      "content": "①권리당원은 제33조제1항 및 제3항의 요건에 충족한 경우 당의 중요 정책과 결정에 대해서 토론을 요청할 수 있다.\n\n②중앙당 사무처는 해당 요건을 충족한 경우 정책에 관한 사항은 정책간담회 또는 정책토론회 등을, 의사결정에 관한 사항은 공개토론 또는 공청회 등을 개최하여 제1항의 토론 요청인에게 설명·토론할 수 있는 권리를 보장하여야 한다.\n\n③제1항의 요청인은 제2항의 토론방법 외에도 당의 의사결정기구에서의 토론을 요청하거나, 하급기관의 결정에 대해 상급기관에서 토론하도록 요청할 수 있다. 이 경우 제36조제2항의 적격심사를 준용한다.\n\n④토론 요청을 받은 해당 기구와 위원회는 토론 요청이 확정된 직후 개최되는 첫 번째 회의에 해당 사안을 심의(토론) 안건으로 상정하여야 한다.\n\n⑤당 사무처는 권리당원의 토론 활성화를 위해 온라인 토론 플랫폼을 구축·운영한다."
