      "title": "# 제35조(전당원투표의 청구 등)",
      "content": "①전당원투표는 당헌 제6조제1항, 당헌 제6조의2의 시행을 위해 권리당원 전원을 대상으로 한 투표를 말한다.(이하‘전당원투표’라 칭한다.) <개정 2026.2.3.>\n\n②전당원투표 청구인은 청구일을 기준으로 권리당원이어야 한다.\n\n③청구인은 권리당원의 서명으로 전당원투표 요청사유를 서면에 구체적으로 명시하여 당무감사원에 전당원투표의 실시를 청구할 수 있다. 이때 청구를 위한 서명인의 수는 제37조제1항에 명시된 전당원투표 발의 서명인 수의 100분의 10을 충족하여야 한다. <개정 2022.8.19.>\n\n④구체적인 청구절차와 방법, 적격심사 기준과 절차는 당무감사원의 의결로, 선거관리 및 투표에 관한 사항은 중앙당선거관리위원회의 의결로 정한다.\n\n⑤본조의 권리당원은 전당원투표권을 가진 권리행사당원으로서, 당규 제5조(선거권) 제1항의 권리당원을 말한다. <개정 2026.2.3.>"
