      "category": "당규",
      "section": "Ⅳ. 당 규",
      "title": "# 제38조(전당원투표의 시행)",
      "content": "①전당원투표는 찬성 또는 반대를 선택하는 형식으로 실시하되, 투표방법은 ARS투표, 인터넷투표로 한다. 구체적인 절차와 방법은 선거관리위원회의 의결로 정한다. <개정 2019.5.29.>\n\n②전당원투표 운동기간은 발의일로부터 선거일까지로 하되, 20일 이상 30일 이내의 범위 안에서 선거관리위원회가 정한다.\n\n③전당원투표는 전당원투표권자 총수의 3분의 1 이상의 투표와 유효투표 총수 과반수의 찬성으로 확정한다.\n\n④전당원투표의 결과는 결과가 확정되는 날에 공표하고, 그 결과를 해당 정책 및 결정에 반영하여야 한다.\n\n⑤전당원투표사무의 관리에 필요한 비용은 선거관리위원회가 부담하되, 그 외에 서명요청활동, 전당원투표 운동 등을 위해 지출한 비용은 청구인이 부담한다."
