      "content": "①일반당비는 권리당원이 정기적으로 매월 납부하는 당비를 말한다.\n\n②권리당원은 월납 기준 1,000원 이상의 당비를 납부하여야 한다. 다만, 권리당원이 고령, 장애인, 국가유공자, 청소년이거나 상당한 사유가 있는 때에는 당무위원회의 의결로 일반당비를 면제할 수 있다. <개정 2022.2.9.>\n\n③백년당원으로 선정된 권리당원은 월납 기준 3,000원 이상의 당비를 연납하여야 한다.\n\n④중앙당 또는 시·도당에 납부되는 제2항의 당비는 매월 중앙당에서 정산한다.\n\n⑤기타 필요한 사항은 당대표가 최고위원회의 의결을 거쳐 정한다."
