      "content": "더불어시민당에서 승계된 당원은 당원자격심사위원회의 심사·판정에 따라 비당원(당원 무효) 판정 등을 받을 수 있으며, 이와 관련한 구체적인 심사 기준과 절차는 제20조를 제외한 제4장 당원자격심사에 정한 바를 준용하고, 최고위원회의 의결로 확정한다."
