      "section": "Ⅳ. 당 규",
      "title": "# 1. 지역당원 입당원서",
      "content": "* 개인정보 변동 시 반드시 해당 시·도당 또는 중앙당으로 연락주시기 바랍니다.\n* ※는 필수기재사항입니다.\n\n- **※ 성명**: \n- **※ 주민번호**: (생년월일 및 주민등록번호 뒷자리 첫째 자리까지 필수 기재)\n- **※ 휴대전화**: \n- **이메일**: \n- **※ 주소**: \n- **장애인 여부**: □ 예 / □ 아니오\n- **대학생 / 대학원생 여부**: □ 예 / □ 아니오\n- **주요 경력 및 공직선거 출마 경력**: \n- **희망 활동부문**: □ 노동 □ 농어민 □ 을지키기 □ 직능 □ 다문화 □ 사회적경제 □ 소상공인 □ 장애인 중 택 1  \n  *(희망활동 부문 체크 시 일반지역당원 및 해당위원회에 소속되어 활동하게 되며 필수사항이 아닙니다.)*\n\n※ 당 사무처의 요구가 있을 경우 거주자 증명서 (주민등록등본, 재직증명서, 재학증명서 등)를 제출하여야 함  \n※ 당규 제2호 당원및당비규정 제7조에 따라 허위로 거주지를 등재하였거나 등재된 정보에 대한 당의 사실 확인요청에 응하지 않을 경우 권리가 제한되거나 징계 대상이 될 수 있습니다.\n\n본인은 더불어민주당에 입당하고자 입당원서를 제출합니다.  \n20  년     월     일  \n- 본인: (인 또는 서명) *(반드시 자필서명하여야 합니다.)*  \n- 추천인: (인) / 추천인 연락처:  \n**더불어민주당 귀중**\n\n---"
