      "content": "* 권리당원은 매월 1,000원 이상의 당비를 납부하여야 합니다.\n* 당비 약정 취소를 요청하는 경우 해당 시·도당으로 꼭 연락하여 주시기 바랍니다.\n\n- **결제정보 안내**: ※ 은행, 휴대전화 결제 시 사용자와 가입자가 다를 경우(가족에 한함) 실가입자의 이름과 주민등록번호, 본인과의 관계를 기재해 주시기 바랍니다.\n- **당비납부자**:\n  - 약정금액: 금             원 (₩           )\n  - 성명:\n  - 주민번호: [ ][ ][ ][ ][ ][ ] - [ ][*][*][*][*][*]\n  - 본인과의 관계:\n\n- **결제방법**:\n  - [자동이체] 은행명: / 계좌번호:\n  - [휴대전화결제] 전화번호: / 통신사: □ SKT □ KT □ LGU+\n  *(※ 통신사 소액결제 서비스 차단 시 결제가 되지 않습니다.)*  \n  *(은행자동이체 결제일은 매월 25일, 휴대전화 결제일은 매월 15일 경입니다. / 은행자동이체 시 휴대폰과 번호로 된 계좌번호는 출금이 불가능합니다. / 직접납부의 경우 해당 시·도당으로 연락주시기 바랍니다.)*\n  - 당비납부자와 결제계좌가 상이한 경우(가족에 한함) 본인은 결제계좌의 구두동의 위임을 받아 진행합니다.\n  - 1년 이상 당비가 체납 된 경우 사전통지 없이 자동이체 등록을 직권해지 합니다.\n\n- **개인정보 활용동의** (미동의 시 당비납부가 되지 않습니다):\n  - **개인정보 수집 및 이용동의서**: 수집 및 이용목적(일상적인 정당활동 및 자동이체, 소액결제를 통한 요금 수납), 수집항목(성명, 주민등록번호, 생년월일, 주소, 연락처, 계좌 및 결제정보, 기타 입당원서 기재사항), 이용 및 보유기간(개인정보의 수집 및 이용목적 달성 시 까지) [동의함 □]\n  - **개인정보 제3자 제공동의서**: 제공받는 자(자동이체 참가 금융기관, 통신사, 결제대행사, 정당이 지정한 개인정보 처리 수탁기관 등), 제공목적(자동이체서비스 제공 및 동의 사실 통지, 고객센터 운영 등), 제공항목(성명, 성별, 생년월일, 연락처, 결제사명, 결제자명, 계좌, 전화번호), 보유기간(동의일부터 자동이체의 종료일(해지일)까지. 단, 관계법령 또는 당규에 따라 보존이 필요한 경우 해당기간 동안 보관) [동의함 □]\n\n본인은 위와 같이 당비 약정을 신청하며 개인정보 제공(개인정보 수집 및 이용, 개인정보 제3자 제공)에 동의합니다.  \n본인: (인 또는 서명) *(반드시 자필서명하여야 합니다.)*  \n*연간 10만원까지는 세액공제를, 10만원을 초과하는 금액에 대해서는 소득공제를 받으실 수 있습니다.(정치자금법 제59조 및 조세특례제한법 제76조)*\n\n개인별기록카드성    명 (한글)성 별이메일주민등록번호휴대전화집전화현 주 소(우)\n\n복무기간    년    월    일   ~          년     월     일(    년    개월)병군    번제대구분역군 병 과계급면제사유기간근무 및 활동내용직위정당및사회경력보 유 기 간정 당 명당 직 명변경 사유당적     년    월 ～     년    월      년    월 ～     년    월 변경     년    월 ～     년    월      년    월 ～     년    월 공직선거선거명(년도)선거구명소속정당명당선여부선거(      년)선거(      년)선거(      년)출마경력선거(      년)선거(      년)\n\n위 사실과 틀림없음을 증명함\n\n년      월      일     신청인               탈당 및 복당신청 사유서작성일 :\n\n작성자 :\n\n탈 당 일탈    당사    유복당신청일복    당사    유및향    후활    동계    획더불어민주당 당원자격심사위원회 귀중법정대리인 동의서만 18세 미만 미성년자의 법정대리인으로서 더불어민주당의복당신청(「정당법」제23조제1항)에 대해 동의합니다.\n\n성명주민등록번호법정대리인주소관계<유 의 사 항>동의 내용이 사실과 다를 경우 이에 대한 민ㆍ형사상 및 행정상 책임은 작성자에게 있음을 알려드립니다.\n\n※ 당 사무처의 요구가 있을 경우 법정대리인을 증명할 수 있는 서류(가족관계증명서 등)를 제출하여야 함\n\n년     월     일법정대리인                  (서명 또는 날인)\n\n더불어민주당 귀중"
