      "content": "①원내대표 선출을 위한 선거인명부의 작성·열람·이의신청·정정·확정·교부 등과 관련한 사항은 원내대표선거관리위원회(원내대표선거관리특별분과위원회)가 한다.\n\n②제1항의 시행을 위해 필요한 구체적인 사항은 원내대표선거관리위원회(원내대표선거관리특별분과위원회)의 의결로 정한다."
