      "content": "①다음 각 호에 해당하는 자는 선거운동을 할 수 없\n\n다. 다만, 후보자의 배우자와 직계 존·비속 및 형제자매인 경우에는 그러하지 아니한다.\n\n1. 선거관리위원회의 위원\n\n2. 중앙당 및 시·도당 사무직당직자\n\n3. 중앙당 사무처 소속 위원회 위원장, 중앙당 및 시․도당 전국위원회급 위원회 위원장, 중앙당 및 시․도당 상설위원회급 위원회 위원장 <개정 2025.7.2.>\n\n4. 당대표, 원내대표, 최고위원, 국회부의장, 전국당원대회 의장단, 중앙위원회 의장단, 시 도당위원장, 사무총장 및 사무부총장, 정책위원회 의장, 정책연구소의 장과 차급의 장, 원내수석부대표 및 원내대변인, 중앙당 및 시 도당 대변인단, 중앙당 및 시 도당 윤리심판위원장 및 위원, 중앙당 및 시 도당 선출직공직자평가위원장 및 위원, 당무감사위원장 및 위원 <신설 2025.7.2., 개정 2026.8.3.>\n\n5. 그 밖에 선거관리위원회가 선거운동을 할 수 없는 자로 결정한 중앙당 및 시·도당 정무직당직자 <신설 2025.7.2.>\n\n②원내대표 선거의 선거운동은 후보자만 가능하고 어떠한 경우에도 선거운동원을 둘 수 없다."
