      "content": "①당대표 비서실은 당대표의 비서업무를 수행한다.\n\n②당대표 비서실장은 당대표의 지시를 받아 비서실의 업무를 총괄한다.\n\n③당대표 비서실에 2명 이하의 정무직 부실장과 사무직 당직자를 둔다.\n\n④당대표 비서실은 다음 사항을 분장한다.\n\n1. 당대표 업무기획에 관한 사항\n\n2. 당대표 메시지 작성에 관한 사항\n\n3. 국제협력에 관한 사항\n\n4. 통일준비에 관한 사항"
