      "content": "①예산결산위원장은 위원회를 대표하고 회무를 총괄한다.\n\n②예산결산위원장 및 위원은 당대표의 추천으로 당무위원회의 의결을 거쳐 임명하고, 부위원장은 위원 중에서 호선으로 선출한다.\n\n③부위원장은 위원장을 보좌하고, 위원장이 궐위되거나 기타의 사유로 직무를 대행할 수 없는 경우에는 당대표가 지명하는 부위원장이 그 직무를 대행한다."
