      "content": "노동국은 다음 사항을 분장한다. <개정 2024.6.12.>\n\n1. 노동부문 정책당원조직의 확대와 관리에 관한 사항 <신설 2024.8.5.>\n\n2. 노동부문 정책당원활동 및 지원업무에 관한 사항\n\n3. 각종 노동단체와의 교류와 협력에 관한 사항\n\n4. 전국노동위원회 업무지원에 관한 사항\n\n[종전 제85조 제4호, 제5호, 제6호, 제7호는 제85조의2로 이동 <2024.6.12.>]"
