      "content": "의2(디지털전략실)①디지털전략실은 제77조제4항의 업무를 전담하는 사무부총장의 지시를 받아 스마트정당 실현과 당의 플랫폼 구축 등 정당현대화 및 디지털소통 업무를 담당한다. <개정 2022.9.19.>\n\n②디지털전략실은 다음 사항을 분장한다. <개정 2022.9.19.>\n\n1. 디지털전략 수립 및 사업기획에 관한 사항\n\n2. 온라인 네트워크 관리·운영에 관한 사항\n\n3. 온라인 지지자의 소통·조직에 관한 사항\n\n4. <삭제 2026.8.3.>\n\n5. 디지털매체 및 뉴미디어를 통한 홍보기획 및 사업에 관한 사항\n\n6. 스마트정당 및 AI정당에 관한 기획 및 구축에 관한 사항 <개정 2026.8.3.>\n\n7. 당 공식 홈페이지 및 디지털매체 관리·운영에 관한 사항\n\n8. <삭제 2024.8.5.>\n\n9. <삭제 2026.8.3.>\n\n10. 당무 온라인화에 관한 사항\n\n11. <삭제 2024.8.5.>\n\n12. <삭제 2026.8.3.>\n\n13. <삭제 2026.8.3.>\n\n14. 영상홍보물 기획과 제작에 관한 사항\n\n15. 당의 사진·영상자료 촬영 및 정리·운영에 관한 사항\n\n16. 온라인 당원청원시스템 구축에 관한 사항 <신설 2022.8.19.>\n\n17. 기타 디지털미디어 및 플랫폼에 관한 사항 <개정 2026.8.3.>\n\n18. <삭제 2024.8.5.>[종전 제96조 제2항 제6호, 제7호, 제8호, 제9호, 제10호는 제96조의2 제2항으로 이동<2022.9.19.>]"
