      "title": "# 제100조(정책조정회의)",
      "content": "①정책위원회 의장은 당 분과위원회간의 정책조정을 위하여 정책조정회의를 소집한다.\n\n②정책조정회의는 정책위원회 의장, 수석부의장, 정책조정위원장, 분과위원장 및 당대표가 정책위원 중 최고위원회와 협의를 거쳐 임명하는 약간 명의 위원으로 구성한다.\n\n③소관 분야의 분과위원회는 정책조정회의의 결정을 따라야 한다."
