      "content": "①시·도당당원대회의 소집은 시·도당당원대회 의장이 한다. 의장이 궐위 되었거나 소집하지 아니하면 부의장이 소집하고, 부의장이 궐위 되었거나 소집하지 아니하면 시·도당 위원장이 소집하며, 시·도당 위원장이 궐위 되었거나 소집하지 아니하면 준비위원장이 소집한다. <개정 2024.6.12.>\n\n②제1항의 소집권자 모두가 궐위 되었거나 소집을 기피하면 당대표가 최고위원회의 의결을 거쳐 소집권자를 지명한다.\n\n③준비위원장은 시·도당당원대회의 일시와 장소, 의제 및 대의원명부를 대회 개최일 7일 전까지 중앙당에 보고하여야 한다. 다만, 상당한 사유가 있을 경우에는 상급당부의 허락을 받아 보고 기한을 변경할 수 있다. <개정 2024.6.12.>\n\n④준비위원장은 시·도당당원대회 개최일 5일 전까지 대회 일시와 장소 및 의제를 명시하여 시·도당사 게시판 및 중앙당 인터넷 홈페이지에 공고하고 대회 개최일 2일 전까지 대의원에게 통지하여야 한다. <개정 2024.6.12.>"
