      "content": "①지역당원대회 개최를 위한 지역당원대회준비위원장(이하 “준비위원장”이라 한다)은 지역위원장이 맡는다. <개정 2024.8.5.>\n\n②준비위원장은 지역당원대회의 준비와 진행에 관한 사무를 관장한다. 다만, 선거관리에 대하여는 선거관리위원회의 지시에 따라야 한다.\n\n③준비위원장은 임명받은 날로부터 45일 이내에 지역당원대회를 완료하여야 한다.[전문개정 2024.6.12.]"
