      "title": "# 제59조(지역위원장 선출과 임기)",
      "content": "①지역위원장은 정기전국당원대회 개최일 전까지 선출하고, 당무위원회의 인준으로 확정하여 당대표가 임명한다. 다만, 사고위원회, 당무위원회가 인준한 지역구 국회의원 후보자의 경우에는 그러하지 아니하다. <개정 2024.6.12.>\n\n②제1항 단서의 지역구 국회의원 후보자는 당무위원회가 인준하는 때 별도의 절차 없이 지역위원장에 선출된 것으로 본다.\n\n③국회의원 선거가 종료된 직후 조직강화특별위원회가 모든 지역위원회에 대해 감사를 실시한 후, 사유가 인정되는 때에는 사고위원회로 판정한다.\n\n④지역위원장의 임기는 다음에 개최되는 정기전국당원대회 개최일 전에 위원장이 새로 선출되는 때까지로 한다. <개정 2024.6.12.>\n\n⑤지역위원장이 사퇴하고자 하는 때에는 사무총장을 경유하여 당대표에게 사퇴서를 제출하여야 한다. ➅지역위원장이 공직선거에 후보자추천을 신청하기 위하여 사퇴한 경우, 후보자추천신청 철회 등 사퇴 사유가 해소되면 최고위원회 의결을 거쳐 지역위원장직에 복귀한다. <개정 2026.8.3.>"
