      "content": "①포상의 종류는 1급 포상·2급 포상 및 포상에 준하는 감사장 등으로 나눈다.\n\n②포상의 종류에 따른 포상권자는 다음 각 호와 같다.\n\n1. 1급 포상 : 당대표\n\n2. 2급 포상 : 당대표, 중앙당 각 기관의 장 또는 시·도당위원장\n\n3. 기타의 포상 : 당대표, 중앙당 각 기관의 장 또는 시·도당위원장\n\n③포상안은 최고위원회 보고 또는 시·도당상무위원회의 심사·의결로서 확정된다.\n\n④당대표는 특별한 공로가 있다고 인정되는 당원 등에 대하여 제10조(포상의 시기와 방법)의 규정에도 불구하고 최고위원회의 의결을 거쳐 특별포상을 할 수 있다."
