      "section": "Ⅳ. 당 규",
      "title": "# 제15조(결정의 종류와 방법)",
      "content": "①중앙당윤리심판원의 결정은 징계처분, 기각, 각하, 재심인용, 재심기각 등으로 한다. <개정 2021.4.23.>\n\n②중앙당윤리심판원의 결정 방법은 사안에 따라 무기명비밀투표, 거수 등으로 할 수 있다.\n\n③제1항 결정의 내용은 다음 각 호와 같다.\n\n1. 징계처분 : 징계혐의가 인정되는 경우 내리는 결정\n\n2. 기각 : 징계청원이 이유가 없다고 인정될 때 내리는 결정\n\n3. 각하 : 징계시효완성 또는 징계절차에 위배되는 징계청원에 대한 결정\n\n4. 재심인용 : 재심신청의 이유가 인정될 경우 내리는 결정(가중처분 또는 감경처분, 징계취소 등) <신설 2021.4.23., 개정 2022.12.30.>\n\n5. 재심기각 : 재심신청의 이유가 없다고 인정될 경우 내리는 결정 <신설 2021.4.23.>"
