      "content": "①징계처분의 종류와 내용은 다음 각 호와 같다.\n\n1. 제명 : 징계대상자의 당적을 박탈하고 강제 출당하는 징계처분\n\n2. 당원자격정지 : 징계대상자의 당직은 자동 해제되고, 징계기간 동안 당원의 권리행사와 당직 수임이 정지되는 징계처분\n\n3. 당직자격정지 : 징계기간 동안 당원의 권리행사를 제외한 당직의 행사와 수임이 정지되는 징계처분\n\n4. 경고 : 징계대상자에게 서면으로 주의를 촉구하는 징계처분\n\n②제1항 제2호 및 제3호 규정에 따른 정지기간은 1개월 이상 2년 이하로 한다.\n\n③징계 후 추가 징계사유가 발생한 경우에는 특별한 사정이 없는 한 이전 징계보다 중한 징계를 한다.\n\n④여러 개의 징계사유가 경합되는 경우에는 그 중 책임이 가장 무거운 사유에 해당하는 징계처분보다 한 단계 위의 징계처분으로 의결할 수 있다.\n\n⑤이 외의 징계처분과 관련한 세부사항은 중앙당윤리심판원이 정한다.\n\n⑥제14조(징계사유)에 해당되는 상당한 이유가 있고, 사유의 중대성으로 인하여 긴급히 업무를 정지시켜야 할 필요성이 인정되는 경우 윤리심판원 결정으로 당직직위해제를 할 수 있다."
