      "content": "이 규정 제14조의 징계사유가 발생한 날로부터 3년이 경과하면 징계하지 못한다. 다만, 성범죄의 경우 징계시효를 두지 아니하며, 기타 성비위의 경우 징계시효를 5년으로 한다. <개정 2022.12.30.>"
