      "content": "①입당 후 6개월이 지난 당원은 윤리규범 위반 및 이 규정 제14조의 징계사유에 해당한다고 판단되는 다른 당원에 대하여 징계를 청원할 수 있다.\n\n②제1항에 따라 징계청원을 하는 경우 청원인은 징계청원서<별지 제2호 서식>에 징계사유에 해당하는 피청원인의 혐의사실을 객관적으로 입증 또는 소명할 수 있는 근거를 적시하거나 첨부하여 심판원에 제출하여야 한다.\n\n③청원인이 허위의 내용이나 확인되지 않은 사실 또는 위조·변조된 자료로 징계청원을 하는 경우에는 이 규정 제14조(징계사유) 및 제30조(무고에 대한 조치)에 따라 징계의 대상이 된다."
