      "content": "①중앙당윤리심판원은 윤리규범 제15조(교육의무)에 따라 당원이 윤리규범과 당헌·당규 등 당의 규율을 준수하도록 당 소속 선출직공직자 및 당직자,당원에 대하여 윤리규범 등 당의 윤리기강 확립에 관한 교육을 당헌당규에 따라 연 1회 이상 실시할 수 있다."
