      "content": "①사무총장은 위원회의 업무처리에 필요한 인력과 예산을 지원하여야 한다.\n\n②위원회에 파견명령을 받은 사무직당직자는 위원장의 지휘를 받아 선거관리 업무를 지원하여야 한다."
