      "category": "당규",
      "section": "Ⅳ. 당 규",
      "title": "# 제2조(설치 및 구성)",
      "content": "①당대표는 대통령선거, 국회의원총선거, 전국동시지방선거 등에 대비하기 위하여 선거기획단(이하 ‘기획단’이라 한다)을 설치할 수 있다.\n\n②기획단은 단장과 부단장을 포함하여 15명 내외의 위원으로 구성한다.\n\n③기획단의 단장과 부단장, 위원은 당대표가 임명한다."
