      "content": "①중앙선거대책위원회의 실무를 총괄하기 위하여 중앙선거대책위원회 아래에 중앙선거대책본부를 둔다.\n\n②중앙선거대책본부에는 본부장을 두고, 약간 명의 부본부장을 둘 수 있다. 필요한 경우 공동본부장직을 둘 수 있다.\n\n③제2항의 본부장과 부본부장은 당대표가 중앙선거대책위원장의 추천을 받아 최고위원회의 심의를 거쳐 임명한다.\n\n④본부장은 본부를 총괄하며, 본부장이 일시적으로 직무를 수행할 수 없는 때에는 본부장이 지명하는 부본부장이 직무를 대행한다. 다만, 본부장이 직무대행을 지명하지 아니한 때에는 중앙선거대책위원장이 지명한다.\n\n⑤중앙선거대책본부 아래에는 종합상황실 및 실무 분과별 본부를 두고, 기타 필요한 기구를 둘 수 있다."
