      "content": "①당헌·당규에 정함이 없는 선거운동과 관련된 제반의 사항은 중앙선거대책위원회가 의결로 정하거나 시행규칙을 제정하여 시행할 수 있다.\n\n②각급 선거대책기구 운영에 필요한 사항은 중앙선거대책위원회가 의결로 정하거나 시행규칙을 제정하여 시행할 수 있다.\n\n③제1항 및 제2항은 당헌·당규에 반하지 아니하여야 한다."
