      "content": "①예비후보자자격심사에 대한 이의신청 처리를 위하여 중앙당과 시·도당에 예비후보자자격심사이의신청처리위원회(이하 ‘이의신청처리위원회’라 한다)를 설치한다.\n\n②이의신청처리위원회는 위원장을 포함하여 9명 이하의 위원으로 구성한다.\n\n③중앙당이의신청처리위원회의 위원장과 위원은 최고위원회의 심의를 거쳐 당대표가 임명한다.\n\n④시·도당이의신청처리위원회의 위원장과 위원은 시·도당운영위원회의 심의를 거쳐 시·도당위원장이 당대표에게 추천하고, 최고위원회의 심의를 거쳐 당대표가 임명한다."
