      "title": "# 제15조(설치 및 구성)",
      "content": "①중앙당공직선거후보자추천관리위원회(이하 ‘중앙당공천관리위원회’라 한다) 및 시·도당공직선거후보자추천관리위원회(이하 ‘시·도당공천관리위원회’라 한다)는 공직선거가 실시되는 때 선거일 100일 전까지 설치한다.\n\n②제1항의 기간 내에 시·도당공천관리위원회가 구성되지 아니하는 때에는 최고위원회가 해당 시·도당위원장과 협의하여 구성한다."
