      "category": "당규",
      "section": "Ⅳ. 당 규",
      "title": "# 제26조(소집 및 의사)",
      "content": "①재심위원회의 회의는 재심 신청 마감 이후 2일 이내에 위원장이 소집하여야 하며, 그 밖에 위원장이 필요하다고 인정하는 때, 최고위원회 또는 재적위원 3분의 1 이상의 요구가 있는 때 소집한다. <개정 2020.8.19.>\n\n②위원회는 재적위원 과반수의 출석과 출석위원 과반수의 찬성으로 의결한다.\n\n③재심위원회의 위원장과 위원은 본인이 후보자추천을 신청한 선거구의 후보자 재심사 및 의결에 참여할 수 없다."
