      "content": "➀이 규정과 관련해 당헌·당규에서 정한 사항 외의 세부규칙과 기타 필요한 사항은 비례대표후보자추천관리위원회가 제정하는 시행세칙으로 정할 수 있다. 이 경우 당헌·당규에 반하지 아니하여야 한다. <신설 2020.2.20.>"
