      "content": "①제56조에 따라 비례대표자치구‧시‧군의원선거 후보자 순위선정을 위한 투표를 실시할 경우, 다음 각 호에 해당하는 지역위원회는 임시지역대의원대회 개최를 허용한다.\n\n1. 하나의 비례대표자치구‧시‧군의원선거구 내에 2 이상의 국회의원지역구가 1개로 통합된 선거구\n\n2. 2020년 정기전국대의원대회 이후 해당 선거구 내 2 이상의 지역위원회 중 1 이상의 지역위원회에서 임시지역대의원대회를 통해 상무위원을 추가 선출하여 동일 선거구 내 다른 지역위원회의 상무위원 수와 현격한 차이가 발생한 지역\n\n②제1항에 따라 임시지역대의원대회를 개최할 경우 당헌 제73조제2항의 전단의 구성인원을 준수하여야 한다."
