      "title": "<별지 제2호>",
      "content": "서  약  서본인은 더불어민주당 ____________________선거에 임하면서 아래 사항을 준수할 것을 굳게 서약합니다.\n\n1. 선거운동과정에서 금품·향응제공, 후보자 비방, 흑색선전, 인신공격, 허위사실 공표, 지역감정 조장 등 공명선거를 저해하는 일체의 행위를 하지 않는다.\n\n2. 당헌·당규와 당의 결정을 준수하고 공명정대한 자세로 심사에 임하며 공천결과에 절대 승복한다.\n\n3. 선거 승리를 위하여 당이 필요하다고 결정하는 경우 기득권을 버리고 당의 결정에 따른다.\n\n4. 당선 시 당원으로서의 의무(예, 직책당비 납부 등)를 성실히 이행한다.\n\n년    월    일서 약 인                  (인)\n\n입 회 인                  (인)\n\n입 회 인                  (인)\n\n중앙당  /  ○○○○ 시·도당더불어민주당공직선거후보자추천관리위원회 귀중타당당적말소 서약서정당법 제42조(강제입당등의 금지)제2항 “누구든지 2이상의 정당의 당원이 되지 못한다” 및 정당법 제55조(위법으로 정당에 가입한 죄) “2이상의 정당의 당원이 된 자는 1년 이하의 징역 또는 100만원 이하의 벌금에 처한다”에 따라 누구든지 이중당적을 취득하지 못하도록 하고 있음\n\n본인은 상기의 이중당적금지규정을 충분히 숙지하고 아래 2개항중 하나의 경우에 해당함을 확인합니다.\n\n① 본인은 타당의 당적을 취득한 적이 없으며, 만일 이러한 사실이 허위로 판명될 경우 귀당에서 취하는 어떠한 조치라도 이의 없이 수용함\n\n② 본인은 타당의 당적을 오늘(     년   월   일) 현재 “탈당증명서 수령” (또는 “탈당계의 내용증명 우편발송”)을 통하여 이미 말소하였으며, 만일 이러한 사실이 허위로 판명될 경우 귀당에서  취하는 어떠한 조치라도 이의 없이 수용함 (*탈당 증명서 또는 탈당계 내용 증명 제출)\n\n년    월    일서 약 인                  (인)\n\n중앙당  /  ○○○○ 시·도당더불어민주당공직선거후보자추천관리위원회 귀중"
