      "content": "①이 규정의 시행을 위해 필요한 구체적인 사항은 위원회의 의결로 정할 수 있다. 이 경우 당헌·당규에 반하지 아니하여야 한다.\n\n②지역위원장에 대한 당무위원회의 인준 권한은 위원회에 위임할 수 없으며, 필요시 당대표 또는 최고위원회에 위임하여야 한다."
