      "content": "①누구든지 승진, 임용, 기타 인사기록에 관하여 허위 또는 부정의 진술, 기재, 증명, 보고를 하여서는 아니 된다.\n\n②인사기록에 관한 자료는 사무총장의 승인 없이 일체 열람하거나 유출할 수 없다.\n\n③제1항 및 제2항을 위배하는 경우에는 윤리심판원에 회부하여 징계토록 한다."
