      "section": "Ⅳ. 당 규",
      "title": "# 제9조(선거권 및 피선거권 제한)",
      "content": "①다음 각 호에 해당하는 자는 대통령선거후보자 선출을 위한 선거권을 제한한다.1.공직선거법 제18조(선거권이 없는 자)에 해당하는 자\n\n2. 당규 제7호(윤리심판원규정) 제28조(징계결정의 확정시기)에 따라, 제16조(징계처분의 종류)제1항제1·2호의 징계처분이 확정된 자\n\n3. 기타 당헌·당규에 의해 당적을 박탈당하거나 당원자격이 정지된 자\n\n②다음 각 호에 해당하는 자는 대통령선거후보자 선출을 위한 피선거권을 제한한다.\n\n1. 공직선거법 제19조(피선거권이 없는 자)에 해당하는 자\n\n2. 당규 제7호(윤리심판원규정) 제28조(징계결정의 확정시기)에 따라, 제16조(징계처분의 종류)제1항제1·2호의 징계처분이 확정된 자\n\n3. 기타 당헌·당규에 의해 당적을 박탈당하거나 당원자격이 정지된 자\n\n③제1·2항의 적용여부, 적용시효 등 구체적인 기준과 방법은 선거관리위원회가 정한다."
