      "content": "①국민여론조사(이하 이 조에서 “조사”라 한다)는 이동통신사로부터 제공받은 전체 안심번호를 대상으로 더불어민주당 지지의사를 밝히거나 지지하는 정당이 없다고 응답한 선거권자에 한해 전화면접 방법으로 실시한다.\n\n②중앙선거관리위원회에 요청하는 안심번호의 할당 기준은 다음 각 호에 따르며, 안심번호를 요청한 날 직전 월(月) 말일(日)의 18세 이상 인구 구성비를 기준으로 한다.\n\n1. 성별 : 남성, 여성\n\n2. 연령별 : 18세~20대, 30대, 40대, 50대, 60세 이상\n\n3. 지역별 : 7개 권역별(서울, 인천·경기, 충청, 호남, 부산·울산·경남, 대구·경북, 강원·제주)\n\n③이동통신사별로 요청하는 안심번호의 비율은 다음 각 호에 따른다. 이동통신사가 다수의 번호를 갖고 있는 동일가입자의 경우 1개 번호로 제공하도록 요청한다.\n\n1. SKT 50%\n\n2. KT 30%\n\n3. LGU+ 20%\n\n④조사는 2개 기관에서 유효응답이 각 1,200표본이 될 때까지 실시한다.\n\n⑤본 질문은 ‘더불어민주당 대통령선거후보자 적합도’로 한다.\n\n⑥제14조(예비경선 실시방법)제6항의 여론조사 실시기간 내에 각 1,200표본을 완료하지 못하는 때에는 0.5~2.0 범위 내에서 선거관리위원회의 결정에 따라 가중치를 부여하여 환산한다.\n\n⑦국민여론조사의 질문 설계 등 구체적 방법은 선거관리위원회의 의결로 정한다."
