      "content": "①당원여론조사(이하 이 조에서 “조사”라 한다)는 당원명부에 기재된 당원을 대상으로 한 전화면접 방법으로 실시하되, 권리당원(이하 이 조에 한하여 전국대의원을 포함한다)과 일반당원을 구분하지 않고 실시한다.\n\n②조사는 당헌 제15조(지위와 구성)제2항제19호에 해당하는 전국대의원 구성비를 기준으로 17개 광역시·도별로 사전에 무작위로 할당 추출하여 실시한다. 이 경우 성과 연령에 따른 할당은 하지 않는다.\n\n③본 질문은 ‘더불어민주당 대통령선거후보자 적합도’로 한다.\n\n④조사는 제14조(예비경선 실시방법)제6항의 여론조사 실시 기간 내에 2개 기관에서 각 1,200표본이 될 때까지 실시하되, 각 1,200표본을 완료하지 못하는 때에는 0.5~2.0 범위내에서 선거관리위원회의 결정에 따라 가중치를 부여하여 환산한다.\n\n⑤당원여론조사의 질문 설계 등 구체적 방법은 선거관리위원회의 의결로 정한다."
