      "content": "선거인단은 전국대의원, 권리당원선거인단, 재외국민선거인단, 국민선거인단이 있으며 다음 각 호에 따라 구성한다.\n\n1. 전국대의원은 당헌 제15조제2항에 따른 대의원으로 구성한다. 단, 당헌 제15조제2항제21호의 재외국민대의원은 본조 제3호에 따라 재외국민선거인단에 포함한다.\n\n2. 권리당원선거인단은 당헌 제5조(구분)제1항 및 당규 제2호(당원및당비규정)제5조(선거권)에 따른 권리당원으로 구성한다.\n\n3. 재외국민선거인단은 당헌 제15조제2항제21호에 따른 재외국민대의원과 해외에 거주하는 권리당원으로 구성한다.\n\n4. 국민선거인단은 이동통신사로부터 제공받은 안심번호를 대상으로 제51조(국민선거인단 투표의 방법)에 따라 투표를 완료한 자로 구성한다."
