      "content": "①선거관리위원회는 이 규정 제36조(선거운동을 할 수 없는 자)의 선거운동에 대해서는 그 행위자에 대해 해촉 및 징계요청 등의 조치를 취하되 다음 각 호에 따른다.\n\n1. 선거관리위원회 위원장과 위원 : 위원 해촉 및 당직자격 정지 이상의 중징계\n\n2. 중앙당 및 시·도당 사무직 당직자 : 업무제외 및 정직 이상의 중징계\n\n3. 법령에 따라 선거운동을 할 수 없는 자 : 관련 법령 위반에 따른 고소·고발\n\n4. 제36조(선거운동을 할 수 없는 자)제2항에 해당하는 자 : 윤리심판원 회부\n\n②윤리심판원은 제1항과 관련하여 선거관리위원회의 윤리심판원 회부가 있는 날로부터 3일 이내에 당규 제7호(윤리심판원규정)제15조(결정의 종류와 방법)에 따라 결정하여야 한다."
