      "content": "①제22대 국회의원선거일 기준 18세 이상인 대한민국 국민 중 선거인 명부에 올라있는 자는 선거권이 있다.\n\n②제22대 총선 후보자 추천을 위한 권리행사 시행일은 2024년 2월 1일이며, 후보자 추천 권리를 부여받는 권리당원은 2023년 7월 31일까지 입당한 당원 중 2023년 2월 1일부터 2024년 1월 31일까지 6회 이상 당비를 납부하고 선거인 명부에 올라있는 자를 말한다. 이때 권리행사 시행일 4개월 전인 2023년 10월 1일 이후부터는 당비 체납처리를 금지한다."
