      "content": "①제18조제3항 및 제4항에 해당하는 자는 가산 적용대상에서 제외하고 감산만 적용한다.\n\n②가산은 가장 유리한 것을, 감산은 가장 불리한 것을 적용하되 중복해서 부여하지 않는다."
