      "title": "# 제27조(선거인명부의 열람)",
      "content": "①선거관리위원장은 선거인명부작성기간 만료일의 다음 날 부터 2일간 특정 장소 및 당 인터넷홈페이지에서 선거인명부를 열람할 수 있도록 하여야 한다. 이 경우 선거관리위원장은 선거인이 당 인터넷홈페이지에서 선거인명부를 열람할 수 있도록 기술적 조치를 하여야 한다.\n\n②선거인은 본인의 정보에 한하여 선거인명부를 열람할 수 있다.\n\n③선거관리위원장은 열람 개시일 1일 전까지 제1항의 장소, 기간, 인터넷홈페이지 주소 및 열람방법을 공고하여야 한다."
