      "title": "# 제30조(통보)",
      "content": "①선관위는 제28조에 따라 확정된 권리당원선거인단에게 투표일정 등 투표에 필요한 사항을 휴대전화 문자메시지 등을 통해 1회 이상 안내한다.\n\n②선관위는 제1항에 따른 안내 시 다음 각 호에 해당하는 경선후보자에 대해서는 경선불복, 탈당, 징계결과를 열람할 수 있는 당 온라인플랫폼을 함께 안내한다. 열람방법, 열람기간, 인증절차 등 구체적 사항은 선거관리위원회가 정한다.\n\n1. 제20대 대통령선거 과정에서 대통합 실시로 경선불복, 탈당, 징계 경력에 대한 심사·경선감산 예외를 적용받은 경선후보자\n\n2. 선거일 기준 최근 2년 이내에 당의 요구로 복당하여 탈당 경력에 대한 경선 감산 예외를 인정받은 경선후보자\n\n③경선후보자의 경선불복, 탈당, 징계결과의 열람은 해당 선거구 권리당원 선거인단에 한하며, 열람을 위해서는 본인 인증절차를 거쳐야 한다."
