      "category": "당규",
      "section": "Ⅳ. 당 규",
      "title": "# 제33조(자발적 ARS투표)",
      "content": "①자발적 ARS투표는 1일간 실시하고 투표일은 선관위가 정하되, 당 인터넷홈페이지에 공고하여야 한다.\n\n②자발적 ARS투표 실시에도 불구하고 투표가 완료되지 아니하는 때에는 해당 선거인은 기권한 것으로 본다.\n\n③ARS투표의 진행상황은 공개하지 아니한다.\n\n④기타 자발적 ARS투표에 관한 사항은 선관위에서 결정한다."
