      "content": "①안심번호선거인단은 이동통신사로부터 제공받은 해당 선거구의 전체 안심번호를 대상으로 전화ARS응답방법의 공모에 응한 자를 말한다.\n\n②안심번호선거인단 모집대상은 더불어민주당 지지층과 무당층 응답자를 대상으로 한다."
